window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[222]={"id":"222","numero":222,"titre":"FRCV & Prévention CV","objectifs":[{"id":"222-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la prévention cardio-vasculaire primaire, secondaire et primo-secondaire","contenu":"<p>La <strong><span class=\"kw-def\">prévention cardio-vasculaire</span></strong> se décline en trois niveaux selon le <span class=\"kw-def\">stade</span> de la <span class=\"kw-etio\">maladie athéromateuse</span> chez le patient.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Population cible</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévention primaire</span></strong></td>\n            <td>Sujet sans maladie cardio-vasculaire ni <span class=\"kw-clinique\">lésion</span> vasculaire documentée</td>\n            <td>Réduire l'<strong><span class=\"kw-def\">incidence</span></strong> de la maladie, en <span class=\"kw-clinique\">dépistant</span> et en <strong>contrôlant les <span class=\"kw-def\">facteurs de risque</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévention primo-secondaire</span></strong></td>\n            <td>Sujet asymptomatique mais porteur de <strong><span class=\"kw-clinique\">lésions vasculaires athéromateuses documentées</span></strong> (ex. <span class=\"kw-clinique\">plaque carotidienne</span>), sans accident clinique encore survenu</td>\n            <td>Situation intermédiaire — freiner la progression des lésions infracliniques avant le premier événement</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévention secondaire</span></strong></td>\n            <td>Sujet ayant déjà présenté un <span class=\"kw-alerte\">accident vasculaire</span> ou porteur de lésions vasculaires documentées</td>\n            <td>Réduire le risque de <strong><span class=\"kw-def\">récidive</span></strong> et <strong>ralentir la progression</strong> des lésions</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <strong><span class=\"kw-def\">prévention secondaire</span></strong> répond à quatre exigences (moyen mnémo : <em>« systématique, multirisque, intensive, médicalisée »</em>) :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Systématique</span></strong> : pour tout sujet ayant présenté un accident vasculaire ou ayant une <span class=\"kw-etio\">atteinte artérielle athéroscléreuse</span></li>\n        <li><strong><span class=\"kw-def\">Multirisque</span></strong> : tous les <span class=\"kw-def\">facteurs de risque</span> sont pris en compte</li>\n        <li><strong><span class=\"kw-def\">Intensive</span></strong> : prise en charge optimale pour chacun des facteurs</li>\n        <li><strong><span class=\"kw-def\">Médicalisée</span></strong> : le recours aux médicaments est la règle, avec un <span class=\"kw-def\">suivi</span> médical régulier</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source rattache les « lésions vasculaires documentées » à la <span class=\"kw-def\">prévention secondaire</span> et ne définit pas explicitement le niveau <em>primo-secondaire</em> — la définition ci-dessus est à confirmer (Collège / Notion).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-etio\">AVC</span> · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":0},{"id":"222-2","rang":"A","rubrique":"Définition","titre":"Connaître les facteurs de risque majeurs, indépendants, modifiables (tabac, HTA, diabète, dyslipidémie) et non modifiables (âge, sexe masculin, hérédité)","contenu":"<p>Un <strong><span class=\"kw-def\">facteur de risque</span></strong> est un élément clinique ou <span class=\"kw-ttt\">biologique</span> associé à une augmentation du risque de développer une maladie, <strong>avec relation de causalité</strong>. Il s'oppose au <strong><span class=\"kw-def\">marqueur de risque</span></strong>, simple témoin de la maladie sans lien causal établi.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Facteur de risque</span></strong></td>\n            <td>Le facteur <strong>précède</strong> la maladie ; relation <strong>dose-effet</strong> ; caractère <strong>universel</strong> ; <strong>plausibilité physiopathologique</strong> ; liaison <strong>forte et indépendante</strong>.<br>Sa suppression entraîne une <strong>baisse de l'<span class=\"kw-def\">incidence</span></strong> de la maladie ou de ses complications.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Marqueur de risque</span></strong></td>\n            <td>Son taux varie en même temps que la maladie s'aggrave ou s'améliore, <strong>sans en influencer l'<span class=\"kw-clinique\">évolution</span></strong>. Sa diminution ne modifie pas le <span class=\"kw-def\">pronostic</span> (ex. <span class=\"kw-clinique\">plaque carotidienne</span> à l'<span class=\"kw-imagerie\">échographie</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Les <strong><span class=\"kw-def\">facteurs de risque</span> majeurs</strong>, indépendants, se répartissent en modifiables et non modifiables :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteur</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"3\"><strong>Non modifiables</strong></td><td><strong>Âge</strong></td><td><span class=\"kw-chiffre\">&gt; 50 ans</span> chez l'homme ; <span class=\"kw-chiffre\">&gt; 60 ans</span> chez la femme</td></tr>\n          <tr><td><strong>Sexe masculin</strong></td><td>La différence s'atténue après la <span class=\"kw-clinique\">ménopause</span> (rôle protecteur des œstrogènes) ; risque identique après <span class=\"kw-chiffre\">65-70 ans</span></td></tr>\n          <tr><td><strong>Hérédité</strong></td><td>ATCD familial d'<span class=\"kw-etio\">IDM</span> ou de <span class=\"kw-alerte\">mort subite</span> : parent du 1er degré masculin <span class=\"kw-chiffre\">&lt; 55 ans</span>, ou féminin <span class=\"kw-chiffre\">&lt; 65 ans</span></td></tr>\n          <tr><td rowspan=\"4\"><strong>Modifiables</strong></td><td><strong><span class=\"kw-etio\">Tabagisme</span></strong></td><td><span class=\"kw-etio\">Tabagisme</span> en cours (dès la 1ʳᵉ cigarette/jour) ou sevré depuis <span class=\"kw-chiffre\">&lt; 3 ans</span> — <span class=\"kw-chiffre\">≈ 30 %</span> de la population</td></tr>\n          <tr><td><strong><span class=\"kw-def\">HTA</span></strong></td><td><span class=\"kw-chiffre\">≈ 30 %</span> de la population</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diabète</span></strong></td><td>Traité ou non, <span class=\"kw-bio\">RR 2-3</span> ; risque apparaissant après <span class=\"kw-chiffre\">15-20 ans</span> d'<span class=\"kw-clinique\">évolution</span> — <span class=\"kw-chiffre\">≈ 5 %</span> de la population</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dyslipidémie</span></strong></td><td><span class=\"kw-etio\">Hypercholestérolémie</span> avec <span class=\"kw-bio\">↑ LDLc</span> et <span class=\"kw-bio\">↓ HDLc</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-def\">Diabète</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":0},{"id":"222-3","rang":"A","rubrique":"Définition","titre":"Connaître l’agrégation de facteurs de risque et facteurs de risque indirects (obésité, sédentarité, syndrome métabolique)","contenu":"<p>L'<strong><span class=\"kw-def\">agrégation de facteurs de risque</span></strong> désigne la coexistence, chez un même patient, de plusieurs <span class=\"kw-def\">facteurs de risque</span>. Elle justifie une <strong><span class=\"kw-def\">évaluation globale du risque</span> cardio-vasculaire</strong> plutôt qu'une lecture isolée de chaque facteur.</p>\n      <p>Les <strong><span class=\"kw-def\">facteurs de risque indirects</span></strong> (dits « secondaires ») ne sont pas des facteurs majeurs indépendants mais aggravent le profil de risque :</p>\n      <table >\n        <thead><tr><th>Facteur indirect</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Surpoids</span> · <span class=\"kw-etio\">obésité</span></strong></td><td>Surtout l'<span class=\"kw-etio\">obésité</span> <strong>abdominale</strong> ; composante centrale du <span class=\"kw-def\">syndrome métabolique</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Syndrome métabolique</span></strong></td><td>Agrégation définie de plusieurs anomalies métaboliques (voir ci-dessous)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Sédentarité</span></strong></td><td>Manque d'activité physique régulière</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Insuffisance rénale chronique</span></strong></td><td>Patient considéré d'emblée à haut risque cardio-vasculaire</td></tr>\n          <tr><td><strong>Facteurs psycho-sociaux</strong></td><td><span class=\"kw-clinique\">Conditions socio-économiques défavorables</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"kw-def\">syndrome métabolique</span></strong> est défini par deux classifications de référence :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>NCEP-ATP III (2005)</th><th>IDF (2005)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Tour de taille</strong></td><td><span class=\"kw-chiffre\">≥ 102 cm</span> (H)<br><span class=\"kw-chiffre\">≥ 88 cm</span> (F)</td><td>Européens : <span class=\"kw-chiffre\">≥ 94 cm</span> (H) / <span class=\"kw-chiffre\">≥ 80 cm</span> (F)<br>Asiatiques : <span class=\"kw-chiffre\">≥ 90 cm</span> (H) / <span class=\"kw-chiffre\">≥ 80 cm</span> (F)</td></tr>\n          <tr><td><strong>Pression artérielle</strong></td><td><span class=\"kw-chiffre\">≥ 130/85 mmHg</span></td><td><span class=\"kw-chiffre\">≥ 130/85 mmHg</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Glycémie à jeun</span></strong></td><td><span class=\"kw-bio\">GAJ</span> <span class=\"kw-chiffre\">≥ 1 g/L</span></td><td><span class=\"kw-bio\">GAJ</span> <span class=\"kw-chiffre\">≥ 1 g/L</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Triglycérides</span></strong></td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">≥ 1,50 g/L</span></td><td><span class=\"kw-bio\">TG</span> <span class=\"kw-chiffre\">≥ 1,50 g/L</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">HDL</span>-cholestérol</strong></td><td><span class=\"kw-bio\">HDL-C</span> <span class=\"kw-chiffre\">&lt; 0,40 g/L</span> (H) / <span class=\"kw-chiffre\">&lt; 0,50 g/L</span> (F)</td><td><span class=\"kw-bio\">HDL-C</span> <span class=\"kw-chiffre\">&lt; 0,40 g/L</span> (H) / <span class=\"kw-chiffre\">&lt; 0,50 g/L</span> (F)</td></tr>\n          <tr><td><strong>Seuil diagnostique</strong></td><td><strong>3 critères / 5</strong></td><td><strong>Tour de taille + 2 critères / 4</strong> restants</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège.</strong> Les deux définitions partagent les mêmes seuils de PA, <span class=\"kw-bio\">glycémie</span>, TG et <span class=\"kw-bio\">HDL</span> : seul le <strong>tour de taille</strong> diffère, et l'<strong>IDF en fait un critère obligatoire</strong> alors que le NCEP-ATP III le compte comme un critère parmi cinq.</div>\n      <div class=\"callout callout-info\"><strong>📌 Seuils LiSA — <span class=\"kw-etio\">obésité</span>.</strong> <strong><span class=\"kw-chiffre\">IMC ≥ 30 kg/m²</span></strong> = obésité ; <strong><span class=\"kw-chiffre\">≥ 40 kg/m²</span></strong> = obésité sévère. L'<strong>obésité abdominale</strong> (tour de taille F &gt; <span class=\"kw-chiffre\">80 cm</span> / H &gt; <span class=\"kw-chiffre\">94 cm</span>) est le phénotype le plus à risque CV.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 253 — <span class=\"kw-etio\">Obésité</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":1},{"id":"222-4","rang":"A","rubrique":"Définition","titre":"Connaître les stratégies individuelles de prévention : mesures hygiéno-diététiques et traitements médicamenteux","contenu":"<p>La <strong><span class=\"kw-def\">stratégie individuelle de prévention</span></strong> combine <strong><span class=\"kw-def\">mesures hygiéno-diététiques</span></strong> et <strong>traitements <span class=\"kw-etio\">médicamenteux</span></strong>, dont l'intensité est graduée selon le niveau de risque.</p>\n      <table >\n        <thead><tr><th>Profil de risque (<span class=\"kw-def\">prévention primaire</span>)</th><th>Stratégie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Profil de risque favorable</strong></td><td>Poursuivre les comportements protecteurs</td></tr>\n          <tr><td><strong>Risque faible ou modéré</strong></td><td>Conseils sur la stratégie de prévention <strong>collective</strong></td></tr>\n          <tr><td><strong>Risque élevé</strong></td><td>Prise en charge <strong>médicalisée spécifique</strong> de <span class=\"kw-def\">prévention primaire</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Mesures hygiéno-diététiques</h4>\n      <ul>\n        <li><strong>Alimentation</strong> : selon le <span class=\"kw-def\">Programme national nutrition santé (PNNS)</span> ; régime de type <strong>méditerranéen</strong> — riche en fruits et légumes, en acides gras insaturés (<span class=\"kw-ttt\">huile d'olive</span>), en produits de la mer, pauvre en viande rouge au profit de la volaille et du poisson</li>\n        <li><strong><span class=\"kw-clinique\">Activité physique</span></strong> régulière (modalités détaillées dans l'objectif dédié)</li>\n        <li><strong><span class=\"kw-ttt\">Sevrage</span> tabagique</strong> et <strong><span class=\"kw-etio\">consommation d'alcool</span> modérée</strong></li>\n      </ul>\n      <h4>Traitements <span class=\"kw-etio\">médicamenteux</span></h4>\n      <p>Prise en charge ciblée de chaque <span class=\"kw-def\">facteur de risque</span> modifiable : <strong><span class=\"kw-etio\">tabac</span></strong>, <strong><span class=\"kw-etio\">dyslipidémie</span></strong>, <strong><span class=\"kw-def\">HTA</span></strong>, <strong><span class=\"kw-def\">diabète</span></strong> (cf. items correspondants).</p>\n      <p>En <strong><span class=\"kw-def\">prévention secondaire</span> après un <span class=\"kw-etio\">IDM</span></strong>, l'ordonnance type suit le moyen mnémo <strong><span class=\"kw-def\">BASIC</span></strong> :</p>\n      <table >\n        <thead><tr><th>Lettre</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>B</strong></td><td><span class=\"kw-ttt\">β-bloquant</span> — indiqué seulement en <strong>post-<span class=\"kw-etio\">IDM</span></strong></td></tr>\n          <tr><td><strong>A</strong></td><td><span class=\"kw-ttt\">Antiagrégant plaquettaire</span> — systématique</td></tr>\n          <tr><td><strong>S</strong></td><td><span class=\"kw-ttt\">Statine</span> — cible <span class=\"kw-bio\">LDLc</span> <span class=\"kw-chiffre\">&lt; 0,55 g/L</span> (réduit la <span class=\"kw-def\">mortalité</span> totale et la morbi-mortalité coronarienne)</td></tr>\n          <tr><td><strong>I</strong></td><td><span class=\"kw-ttt\">IEC</span></td></tr>\n          <tr><td><strong>C</strong></td><td><strong>Contrôle des <span class=\"kw-etio\">FRCV</span></strong> : arrêt du <span class=\"kw-etio\">tabac</span>, contrôle de la PA et de la <span class=\"kw-bio\">glycémie</span>, lutte contre la <span class=\"kw-etio\">sédentarité</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-def\">Diabète</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":1},{"id":"222-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence, le risque cardiovasculaire associé et le pourcentage de pathologies cardiovasculaires évitables en cas de prise en charge des facteurs de risque majeurs modifiables (HTA, tabac, diabète, dyslipidémie), connaître l’existence de scores (sans savoir les calculer)","contenu":"<p>Les <strong><span class=\"kw-def\">facteurs de risque</span> majeurs modifiables</strong> sont très <strong>prévalents</strong> en population générale, ce qui fait du contrôle de ces facteurs un enjeu de santé publique majeur.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Facteur de risque</span></th><th><span class=\"kw-def\">Prévalence</span> (population)</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">HTA</span></strong></td><td><span class=\"kw-chiffre\">≈ 30 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Tabagisme</span></strong></td><td><span class=\"kw-chiffre\">≈ 30 %</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diabète</span></strong></td><td><span class=\"kw-chiffre\">≈ 5 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"kw-def\">risque cardio-vasculaire (RCV)</span></strong> est la probabilité de survenue, chez une personne, d'un <span class=\"kw-alerte\">événement CV majeur</span> (décès <span class=\"kw-bio\">CV</span>, <span class=\"kw-clinique\">infarctus</span>, <span class=\"kw-etio\">AVC</span>) sur une période donnée — <strong>habituellement <span class=\"kw-chiffre\">10 ans</span></strong>. Tout patient en <span class=\"kw-def\">prévention primaire</span> avec <strong><span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-etio\">FRCV</span></strong> doit bénéficier d'une évaluation globale du RCV. Ce calcul n'a <strong>pas d'intérêt en <span class=\"kw-def\">prévention secondaire</span></strong> (patients d'emblée à risque très élevé).</p>\n      <p>Il s'appuie sur des <strong><span class=\"kw-def\">scores</span></strong> de risque — à <strong>connaître sans savoir les calculer</strong> :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span></th><th>Population</th><th>Ce qu'il estime</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">SCORE</span></strong></td><td><span class=\"kw-chiffre\">40-65 ans</span></td><td>Risque de <strong><span class=\"kw-def\">mortalité</span></strong> <span class=\"kw-bio\">CV</span> à<span class=\"kw-chiffre\"> 10 ans</span>. Paramètres : âge, sexe, <span class=\"kw-etio\">tabagisme</span>, <span class=\"kw-clinique\">PAS</span>, <span class=\"kw-bio\">cholestérol total</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SCORE2</span></strong> (2021)</td><td><span class=\"kw-chiffre\">40-69 ans</span>, apparemment en bonne santé</td><td>Risque d'événements <span class=\"kw-bio\">CV</span> <strong>mortels et non mortels</strong> (<span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">AVC</span>) à<span class=\"kw-chiffre\"> 10 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">SCORE2-OP</span></strong> <em>(Older Persons)</em></td><td><span class=\"kw-chiffre\">≥ 70 ans</span>, apparemment en bonne santé</td><td>Événements <span class=\"kw-bio\">CV</span> fatals et non fatals à 5 et <span class=\"kw-chiffre\">10 ans</span>, ajustés aux risques concurrents</td></tr>\n          <tr><td><strong><span class=\"kw-def\">SCORE2-Diabetes</span></strong> (2023)</td><td><span class=\"kw-def\">DT2</span> sans MCV athérosclérotique ni atteinte grave d'organe</td><td>SCORE2 + facteurs spécifiques au <span class=\"kw-def\">diabète</span> : âge au diagnostic, <span class=\"kw-bio\">HbA1c</span>, <span class=\"kw-bio\">DFGe</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le RCV est ensuite classé en quatre niveaux :</p>\n      <table >\n        <thead><tr><th>Niveau de risque</th><th>SCORE2 (<span class=\"kw-chiffre\">50-69 ans</span>)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Faible</strong></td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n          <tr><td><strong>Modéré</strong></td><td><span class=\"kw-chiffre\">1 - 4,9 %</span></td></tr>\n          <tr><td><strong>Élevé</strong></td><td><span class=\"kw-chiffre\">5 - 9,9 %</span></td></tr>\n          <tr><td><strong>Très élevé</strong></td><td><span class=\"kw-chiffre\">≥ 10 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>Indication d'une prise en charge des <span class=\"kw-etio\">FRCV</span> : <span class=\"kw-chiffre\">SCORE2 &gt; 7,5 %</span> avant <span class=\"kw-chiffre\">50 ans</span>, <span class=\"kw-chiffre\">&gt; 10 %</span> entre 50 et <span class=\"kw-chiffre\">70 ans</span>, <span class=\"kw-chiffre\">SCORE2-OP &gt; 15 %</span> après <span class=\"kw-chiffre\">70 ans</span>.</p>\n      <div class=\"callout callout-info\"><strong>Patients à haut risque d'emblée</strong> (sans calcul de <span class=\"kw-def\">score</span>) : <span class=\"kw-alerte\">diabétique</span>, <span class=\"kw-alerte\">HTA sévère</span> (<span class=\"kw-chiffre\">≥ 180/110 mmHg</span>), <span class=\"kw-alerte\">insuffisance rénale chronique</span>, <span class=\"kw-alerte\">hypercholestérolémie familiale</span>, <strong><span class=\"kw-def\">prévention secondaire</span></strong> (ATCD de cardiopathie <span class=\"kw-etio\">ischémique</span>, <span class=\"kw-etio\">AVC</span>, AOMI).</div>\n      <div class=\"callout callout-info\"><strong>Piège — <span class=\"kw-def\">SCORE</span> non applicable.</strong> Femme enceinte ; sujet jeune <span class=\"kw-chiffre\">&lt; 40 ans</span> avec plusieurs <span class=\"kw-etio\">FRCV</span> (tables spécifiques) ; sujet très âgé (l'âge devient le facteur dominant).</div>\n      <div class=\"callout callout-info\"><strong>📌 <span class=\"kw-def\">Diabète</span> — LiSA.</strong> L'impact d'un contrôle glycémique intensif sur les événements CV reste débattu. Deux classes récentes ont démontré une <strong>réduction des événements CV</strong> indépendamment du contrôle de l'<span class=\"kw-bio\">HbA1c</span> : les <strong><span class=\"kw-ttt\">inhibiteurs des SGLT2</span></strong> et les <strong><span class=\"kw-ttt\">analogues du GLP-1</span></strong>.</div>\n      <div class=\"callout callout-info\"><strong>Étude INTERHEART — pathologies CV évitables.</strong> Cette étude cas-témoins d'<span class=\"kw-etio\">IDM</span> (toutes régions du monde) confirme que <strong>9 facteurs expliquent ≈ <span class=\"kw-chiffre\">90 %</span> du risque d'<span class=\"kw-alerte\">IDM</span></strong>, dans toutes les classes d'âge et les deux sexes :\n        <ul>\n          <li><strong>6 <span class=\"kw-def\">facteurs de risque</span></strong> : <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">hypercholestérolémie</span> (<span class=\"kw-bio\">ApoB/ApoA1</span>), <span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">obésité abdominale</span>, facteurs psychosociaux</li>\n          <li><strong>3 facteurs protecteurs</strong> : consommation de <span class=\"kw-clinique\">fruits et légumes</span>, <span class=\"kw-clinique\">activité physique</span>, <span class=\"kw-etio\">alcool</span> en consommation modérée</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-def\">Diabète</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span></em></p>","frequence":1},{"id":"222-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le rôle de l’alcool dans le risque cardiovasculaire","contenu":"<p>L'<strong><span class=\"kw-etio\">alcool</span></strong> a un rôle <strong>ambivalent</strong> sur le risque cardio-vasculaire, selon la quantité consommée.</p>\n      <table >\n        <thead><tr><th>Consommation</th><th>Effet sur le risque <span class=\"kw-bio\">CV</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Consommation modérée</strong><br><span class=\"kw-chiffre\">1 à 2 verres/jour</span></td>\n            <td><strong>Facteur protecteur</strong> — surtout le <strong>vin</strong>, et principalement sur le plan <strong>coronarien</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Excès d'<span class=\"kw-etio\">alcool</span></strong><br><span class=\"kw-chiffre\">&gt; 3 verres de vin/jour</span> (homme)<br><span class=\"kw-chiffre\">&gt; 2 verres de vin/jour</span> (femme)</td>\n            <td><span class=\"kw-alerte\">Marqueur de risque cardio-vasculaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège.</strong> L'<span class=\"kw-etio\">alcool</span> en excès est classé comme <strong>marqueur de risque</strong> (témoin) et non comme <span class=\"kw-def\">facteur de risque</span> majeur indépendant. À l'inverse, une consommation modérée figure parmi les <strong>facteurs protecteurs</strong> — d'où une relation décrite en « courbe en J ».</div>\n      <div class=\"callout callout-warn\"><strong>📌 <span class=\"kw-alerte\">Binge drinking</span> — LiSA.</strong> Une <strong>intoxication aiguë</strong> (« binge drinking ») augmente de <strong><span class=\"kw-chiffre\">+ 40 %</span></strong> le risque relatif de <span class=\"kw-etio\">SCA</span> et de mortalité CV en post-intoxication, indépendamment de la consommation chronique. Au-delà de <span class=\"kw-chiffre\">30-40 g/j</span> chroniques : cardiopathie dilatée toxique.</div>","frequence":0},{"id":"222-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le rôle des facteurs psychosociaux dans le risque cardiovasculaire","contenu":"<p>Les <strong><span class=\"kw-def\">facteurs psycho-sociaux</span></strong> participent au risque cardio-vasculaire, principalement à travers les <strong>conditions socio-économiques défavorables</strong>.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Conditions socio-économiques défavorables</span></strong> — classées parmi les <span class=\"kw-def\">facteurs de risque</span> indirects</li>\n        <li><span class=\"kw-clinique\">Dépression</span> et autres <span class=\"kw-clinique\">troubles psychiques</span></li>\n        <li>Catégorie sociale défavorisée, <strong><span class=\"kw-clinique\">isolement social</span></strong></li>\n        <li><strong><span class=\"kw-clinique\">Stress</span></strong> — un stress aigu intense peut induire un <span class=\"kw-clinique\">infarctus</span>, illustré par le <strong><span class=\"kw-etio\">syndrome de Tako-Tsubo</span></strong> (cardiomyopathie de stress)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Piège.</strong> Les facteurs psycho-sociaux ne sont <strong>pas pris en compte dans les scores</strong> de risque (SCORE2, SCORE2-OP) : ils peuvent donc conduire à <span class=\"kw-alerte\">sous-estimer le risque</span> réel d'un patient.</div>","frequence":0},{"id":"222-8","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le rôle de l’hypertriglycéridémie dans le risque cardiovasculaire","contenu":"<p>L'<strong><span class=\"kw-etio\">hypertriglycéridémie</span></strong> participe au risque cardio-vasculaire au sein du <strong>profil d'agrégation des <span class=\"kw-def\">facteurs de risque</span></strong>.</p>\n      <ul>\n        <li>Elle constitue l'un des <strong>cinq critères du <span class=\"kw-def\">syndrome métabolique</span></strong> : <span class=\"kw-bio\">triglycérides</span> <span class=\"kw-chiffre\">≥ 1,50 g/L</span></li>\n        <li>Elle est fréquemment associée à un <span class=\"kw-bio\">HDL-cholestérol bas</span>, à l'<span class=\"kw-etio\">obésité</span> abdominale et à l'insulinorésistance</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source ne mentionne l'<span class=\"kw-etio\">hypertriglycéridémie</span> qu'au travers du seuil du <span class=\"kw-def\">syndrome métabolique</span> ; le mécanisme physiopathologique précis de son rôle dans le risque <span class=\"kw-bio\">CV</span> est à compléter (Collège / Notion, item 223 — <span class=\"kw-etio\">Dyslipidémie</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":0},{"id":"222-9","rang":"B","rubrique":"Étiologies","titre":"Expliquer l’influence de l’excès de poids dans le risque cardiovasculaire","contenu":"<p>L'<strong><span class=\"kw-etio\">excès de poids</span></strong> (<span class=\"kw-etio\">surpoids</span>, <span class=\"kw-etio\">obésité</span>) est un <strong><span class=\"kw-def\">facteur de risque</span> indirect</strong> : il n'agit pas comme un facteur majeur indépendant mais aggrave le profil de risque en favorisant l'<strong>agrégation</strong> des autres facteurs.</p>\n      <ul>\n        <li>Il favorise l'apparition d'une <span class=\"kw-def\">HTA</span>, d'un <span class=\"kw-def\">diabète</span> et d'une <span class=\"kw-etio\">dyslipidémie</span></li>\n        <li>L'<strong><span class=\"kw-etio\">obésité</span> abdominale</strong> est la composante centrale du <span class=\"kw-def\">syndrome métabolique</span>, appréciée par le <strong>tour de taille</strong></li>\n      </ul>\n      <p>Seuils de tour de taille définissant l'<span class=\"kw-etio\">obésité</span> abdominale :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Classification</span></th><th>Homme</th><th>Femme</th></tr></thead>\n        <tbody>\n          <tr><td><strong>NCEP-ATP III</strong></td><td><span class=\"kw-chiffre\">≥ 102 cm</span></td><td><span class=\"kw-chiffre\">≥ 88 cm</span></td></tr>\n          <tr><td><strong>IDF</strong> (Européens)</td><td><span class=\"kw-chiffre\">≥ 94 cm</span></td><td><span class=\"kw-chiffre\">≥ 80 cm</span></td></tr>\n          <tr><td><strong>IDF</strong> (Asiatiques)</td><td><span class=\"kw-chiffre\">≥ 90 cm</span></td><td><span class=\"kw-chiffre\">≥ 80 cm</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 253 — <span class=\"kw-etio\">Obésité</span> · 247 — <span class=\"kw-def\">Diabète</span></em></p>","frequence":1},{"id":"222-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître le bénéfice de l’activité physique pour la prise en charge du risque cardiovasculaire","contenu":"<p>L'<strong><span class=\"kw-clinique\">activité physique</span></strong> régulière figure parmi les <strong>facteurs protecteurs</strong> cardio-vasculaires. Elle est recommandée aussi bien en <strong><span class=\"kw-def\">prévention primaire</span></strong> qu'en <strong><span class=\"kw-def\">prévention secondaire</span></strong>.</p>\n      <ul>\n        <li>Elle agit favorablement sur plusieurs <span class=\"kw-def\">facteurs de risque</span> : <span class=\"kw-etio\">excès de poids</span>, <span class=\"kw-def\">HTA</span>, équilibre <span class=\"kw-bio\">glycémique</span> et <span class=\"kw-bio\">lipidique</span></li>\n        <li>Elle s'intègre aux <strong><span class=\"kw-def\">mesures hygiéno-diététiques</span></strong>, socle de toute stratégie de prévention</li>\n        <li>La lutte contre la <strong><span class=\"kw-etio\">sédentarité</span></strong> fait partie du contrôle des <span class=\"kw-etio\">FRCV</span> en <span class=\"kw-def\">prévention secondaire</span> (volet « C » du moyen mnémo <span class=\"kw-def\">BASIC</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le bénéfice décrit ici est <strong>qualitatif</strong> ; la <strong>quantité d'activité physique à conseiller</strong> fait l'objet de l'objectif suivant.</div>","frequence":0},{"id":"222-11","rang":"B","rubrique":"Prise en charge","titre":"Décrire la quantité d’activité physique à conseiller en prévention cardiovasculaire primaire","contenu":"<p>En <strong>prévention cardio-vasculaire primaire</strong>, l'activité physique conseillée se décrit selon trois paramètres.</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Recommandation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence / durée</strong></td><td><span class=\"kw-chiffre\">≥ 30 minutes</span>, <span class=\"kw-chiffre\">5 jours/semaine</span></td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Autour de <span class=\"kw-chiffre\">60 %</span> de la fréquence maximale théorique (<span class=\"kw-def\">FMT</span> = <span class=\"kw-chiffre\">220 − âge</span>), sans jamais dépasser <span class=\"kw-chiffre\">80 %</span></td></tr>\n          <tr><td><strong>Type d'activité</strong></td><td>Activités d'endurance particulièrement adaptées : <strong><span class=\"kw-ttt\">marche</span></strong>, <strong><span class=\"kw-ttt\">vélo</span></strong>, <strong><span class=\"kw-ttt\">natation</span></strong>, <strong><span class=\"kw-ttt\">jogging</span></strong></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"222-12","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître l’efficacité de la prévention cardiovasculaire centrée sur le patient en soins primaires","contenu":"<p>La <strong><span class=\"kw-def\">prévention cardio-vasculaire centrée sur le patient en soins primaires</span></strong> repose sur le médecin généraliste comme acteur pivot du <span class=\"kw-clinique\">dépistage</span> et du <span class=\"kw-def\">contrôle des facteurs de risque</span>.</p>\n      <ul>\n        <li>Elle suppose une <strong><span class=\"kw-def\">évaluation globale du risque</span> <span class=\"kw-bio\">CV</span></strong> pour tout patient ayant <span class=\"kw-chiffre\">≥ 1</span> <span class=\"kw-etio\">FRCV</span> en <span class=\"kw-def\">prévention primaire</span></li>\n        <li>Elle est d'autant plus efficace qu'elle est <strong>multirisque</strong> (tous les FR pris en compte ensemble) et <strong><span class=\"kw-def\">individualisée</span></strong> (adaptée au profil de risque du patient)</li>\n        <li>En <span class=\"kw-def\">prévention secondaire</span>, elle doit être <strong><span class=\"kw-def\">systématique, intensive et médicalisée</span></strong>, avec un <span class=\"kw-def\">suivi régulier</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> La fiche source ne développe pas les données chiffrées d'efficacité de la prévention centrée sur le patient en soins primaires — à enrichir (Collège de médecine générale / Notion).</div>","frequence":0}],"astuces":[],"strategie":{"principes":"<p>La stratégie individuelle combine <span class=\"kw-ttt\">mesures hygiéno-diététiques</span> (socle commun) et traitements <span class=\"kw-etio\">médicamenteux</span>, <strong>graduée selon le niveau de risque</strong>. La <span class=\"kw-def\">prévention secondaire</span> est <span class=\"kw-def\">systématique, multirisque, intensive et médicalisée</span>.</p><p><strong>Mesures hygiéno-diététiques <span class=\"q\">— socle commun</span></strong></p><p>Activités d'endurance adaptées : marche, vélo, natation, jogging</p><ul><li>Alimentation type <span class=\"kw-ttt\">méditerranéenne</span> (<span class=\"kw-def\">PNNS</span>) : fruits et légumes, acides gras insaturés (<span class=\"kw-ttt\">huile d'olive</span>), produits de la mer</li><li><span class=\"kw-ttt\">Activité physique</span> : <span class=\"kw-chiffre\">≥ 30 min</span>, <span class=\"kw-chiffre\">5 j/semaine</span>, à <span class=\"kw-chiffre\">~60 %</span> de la FMT (<span class=\"kw-chiffre\">220 − âge</span>), sans dépasser <span class=\"kw-chiffre\">80 %</span></li><li><span class=\"kw-ttt\">Sevrage tabagique</span> et consommation d'<span class=\"kw-etio\">alcool</span> modérée</li></ul><p><strong><span class=\"kw-def\">Prévention primaire</span> <span class=\"q\">— graduée selon le risque</span></strong></p><p>Prise en charge ciblée de chaque <span class=\"kw-etio\">FRCV</span> modifiable : <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span></p><ul><li>Profil favorable : poursuivre les <span class=\"kw-clinique\">comportements protecteurs</span></li><li>Risque <span class=\"kw-chiffre\">faible / modéré</span> : conseils de prévention collective</li><li>Risque <span class=\"kw-chiffre\">élevé</span> : prise en charge <span class=\"kw-ttt\">médicalisée spécifique</span></li></ul><p><strong><span class=\"kw-def\">Prévention secondaire</span> <span class=\"q\">— ordonnance BASIC (post-<span class=\"kw-clinique\">IDM</span>)</span></strong></p><p><span class=\"kw-def\">Prévention secondaire</span> = systématique, multirisque, intensive et médicalisée</p><ul><li><strong>B</strong> — <span class=\"kw-ttt\">β-bloquant</span> (seulement en post-<span class=\"kw-etio\">IDM</span>)</li><li><strong>A</strong> — <span class=\"kw-ttt\">antiagrégant plaquettaire</span> (systématique)</li><li><strong>S</strong> — <span class=\"kw-ttt\">statine</span>, cible <span class=\"kw-bio\">LDLc</span> <span class=\"kw-chiffre\">&lt; 0,55 g/L</span></li><li><strong>I</strong> — <span class=\"kw-ttt\">IEC</span></li><li><strong>C</strong> — contrôle des <span class=\"kw-etio\">FRCV</span> : arrêt <span class=\"kw-etio\">tabac</span>, contrôle de la <span class=\"kw-clinique\">PA</span> et de la <span class=\"kw-bio\">glycémie</span>, lutte contre la <span class=\"kw-etio\">sédentarité</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Prévention primaire</span> :</strong> évaluation globale du <span class=\"kw-def\">RCV</span> pour tout patient avec <span class=\"kw-chiffre\">≥ 1 FRCV</span>, via <span class=\"kw-def\">SCORE2</span> (avant <span class=\"kw-chiffre\">70 ans</span>) ou <span class=\"kw-def\">SCORE2-OP</span> (après <span class=\"kw-chiffre\">70 ans</span>), à réévaluer régulièrement.<br><strong>Seuils de prise en charge :</strong> <span class=\"kw-chiffre\">SCORE2 &gt; 7,5 %</span> avant <span class=\"kw-chiffre\">50 ans</span> · <span class=\"kw-chiffre\">&gt; 10 %</span> entre 50 et <span class=\"kw-chiffre\">70 ans</span> · <span class=\"kw-chiffre\">SCORE2-OP &gt; 15 %</span> après <span class=\"kw-chiffre\">70 ans</span>.<br><strong><span class=\"kw-def\">Prévention secondaire</span> :</strong> pas de calcul de <span class=\"kw-def\">score</span> (<span class=\"kw-alerte\">risque très élevé</span> d'emblée) ; <span class=\"kw-def\">suivi</span> médical régulier, prise en charge <span class=\"kw-def\">multirisque, intensive et médicalisée</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient avec ≥ 1 FRCV — quelle stratégie de prévention ? — Premier tri : maladie CV ou lésion vasculaire documentée ?","detail":"<h4>CAT — patient avec <span class=\"kw-etio\">FRCV</span> : évaluation du risque et stratégie de prévention — Premier tri : <span class=\"kw-def\">prévention secondaire</span> <span class=\"kw-bio\">vs</span> primaire, puis niveau de risque</h4>","branches":[{"to":"t-secondaire","label":"Maladie CV documentée (SCA/IDM, AVC, AOMI)","color":"red"},{"to":"q-emblee","label":"Asymptomatique, ≥ 1 FRCV","color":"blue"}]},{"id":"t-secondaire","kind":"terminal","label":"Prévention secondaire","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-alerte\">Maladie CV documentée</span> (<span class=\"kw-etio\">SCA / IDM</span>, <span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">AOMI</span>) ou <span class=\"kw-clinique\">lésion</span> vasculaire athéromateuse documentée → <span class=\"kw-alerte\">risque très élevé</span>, pas de calcul de <span class=\"kw-def\">score</span></li></ul><h4>Principes</h4><ul><li>Prise en charge <span class=\"kw-def\">systématique, multirisque, intensive et médicalisée</span>, avec <span class=\"kw-def\">suivi</span> régulier</li></ul><h4>Ordonnance BASIC (post-<span class=\"kw-clinique\">IDM</span>)</h4><ul><li><span class=\"kw-ttt\">β-bloquant</span> (seulement en post-<span class=\"kw-etio\">IDM</span>)</li><li><span class=\"kw-ttt\">Antiagrégant plaquettaire</span> systématique</li><li><span class=\"kw-ttt\">Statine</span> : cible <span class=\"kw-bio\">LDLc</span> <span class=\"kw-chiffre\">&lt; 0,55 g/L</span></li><li><span class=\"kw-ttt\">IEC</span></li><li>Contrôle des <span class=\"kw-etio\">FRCV</span> : arrêt <span class=\"kw-etio\">tabac</span>, <span class=\"kw-clinique\">PA</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-etio\">sédentarité</span></li></ul><h4>Renvoi</h4><ul><li>Item 339 (<span class=\"kw-alerte\">syndrome coronarien aigu</span>) · Item 340 (<span class=\"kw-alerte\">AVC</span>) · Item 225 (artériopathie oblitérante - anévrysme)</li></ul>"},{"id":"q-emblee","kind":"decision","label":"Patient à haut risque d'emblée ? — Diabète · HTA sévère (≥ 180/110 mmHg) · IRC · hypercholestérolémie familiale","branches":[{"to":"t-emblee","label":"Oui","color":"amber"},{"to":"q-score","label":"Non → calcul du score","color":"blue"}]},{"id":"t-emblee","kind":"terminal","label":"Haut risque d'emblée — PEC médicalisée","color":"amber","detail":"<h4>Patients à haut risque d'emblée</h4><ul><li><span class=\"kw-alerte\">Diabétique</span></li><li><span class=\"kw-alerte\">HTA sévère</span> (<span class=\"kw-chiffre\">≥ 180/110 mmHg</span>)</li><li><span class=\"kw-alerte\">Insuffisance rénale chronique</span></li><li><span class=\"kw-alerte\">Hypercholestérolémie familiale</span></li></ul><h4>Conduite</h4><ul><li>Prise en charge <span class=\"kw-ttt\">médicalisée</span> de chaque <span class=\"kw-etio\">FRCV</span> + <span class=\"kw-ttt\">mesures hygiéno-diététiques</span>, sans calcul de <span class=\"kw-def\">score</span></li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>) · Item 247 (diabète) · Item 223 (dyslipidémie) · Item 264 (<span class=\"kw-ci\">insuffisance rénale</span> chronique)</li></ul>"},{"id":"q-score","kind":"decision","label":"Niveau de risque (SCORE2 / SCORE2-OP) ? — SCORE2 avant 70 ans · SCORE2-OP après 70 ans · calcul inutile en prévention secondaire","branches":[{"to":"t-primaire-faible","label":"Faible / modéré","color":"green"},{"to":"t-primaire-eleve","label":"Élevé / très élevé","color":"amber"}]},{"id":"t-primaire-faible","kind":"terminal","label":"Prévention primaire — mesures simples","color":"green","detail":"<h4>Évaluation</h4><ul><li><span class=\"kw-def\">SCORE2</span> <span class=\"kw-chiffre\">faible (&lt; 1 %)</span> ou <span class=\"kw-chiffre\">modéré (1–4,9 %)</span> (<span class=\"kw-chiffre\">50–69 ans</span>)</li></ul><h4>Conduite</h4><ul><li>Conseils de prévention collective + <span class=\"kw-ttt\">mesures hygiéno-diététiques</span></li><li>Alimentation <span class=\"kw-ttt\">méditerranéenne</span>, <span class=\"kw-ttt\">activité physique</span> régulière, <span class=\"kw-ttt\">sevrage tabagique</span></li></ul><h4>À retenir</h4><ul><li>Pas de traitement <span class=\"kw-etio\">médicamenteux</span> systématique ; poursuivre les <span class=\"kw-clinique\">comportements protecteurs</span></li></ul>"},{"id":"t-primaire-eleve","kind":"terminal","label":"Prévention primaire médicalisée","color":"amber","detail":"<h4>Évaluation</h4><ul><li><span class=\"kw-def\">SCORE2</span> <span class=\"kw-chiffre\">élevé (5–9,9 %)</span> ou <span class=\"kw-chiffre\">très élevé (≥ 10 %)</span></li></ul><h4>Seuils d'indication</h4><ul><li><span class=\"kw-chiffre\">SCORE2 &gt; 7,5 %</span> avant <span class=\"kw-chiffre\">50 ans</span> · <span class=\"kw-chiffre\">&gt; 10 %</span> entre 50 et <span class=\"kw-chiffre\">70 ans</span> · <span class=\"kw-chiffre\">SCORE2-OP &gt; 15 %</span> après <span class=\"kw-chiffre\">70 ans</span></li></ul><h4>Conduite</h4><ul><li>Prise en charge <span class=\"kw-ttt\">médicalisée spécifique</span> + <span class=\"kw-ttt\">mesures hygiéno-diététiques</span> intensives, contrôle de chaque <span class=\"kw-etio\">FRCV</span> (<span class=\"kw-etio\">tabac</span>, <span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">dyslipidémie</span>)</li></ul><h4>Renvoi</h4><ul><li>Item 224 (<span class=\"kw-etio\">HTA</span>) · Item 223 (dyslipidémie) · Item 247 (diabète)</li></ul>"}]},"cards":[{"i":"083eb7460fce","n":222,"o":"222-1","u":"Définition","t":"Connaître la définition de la prévention cardio-vasculaire primaire, secondaire et primo-secondaire","q":"Comment définit-on la prévention cardio-vasculaire primaire ?","a":"<p>La prévention cardio-vasculaire primaire s'adresse à un sujet <strong>sans maladie cardio-vasculaire</strong> ni lésion vasculaire documentée. Son objectif est de <strong>réduire l'incidence de la maladie</strong> en dépistant et en contrôlant les facteurs de risque.</p>"},{"i":"79e6ca7db780","n":222,"o":"222-1","u":"Définition","t":"Connaître la définition de la prévention cardio-vasculaire primaire, secondaire et primo-secondaire","q":"Quelle est la définition de la prévention cardio-vasculaire primo-secondaire ?","a":"<p>La prévention cardio-vasculaire primo-secondaire concerne un sujet <strong>asymptomatique</strong> mais porteur de <strong>lésions vasculaires athéromateuses documentées</strong> (par exemple, une plaque carotidienne), sans accident clinique encore survenu. L'objectif est de freiner la progression des lésions infracliniques avant le premier événement.</p>"},{"i":"ee0a9152634d","n":222,"o":"222-1","u":"Définition","t":"Connaître la définition de la prévention cardio-vasculaire primaire, secondaire et primo-secondaire","q":"Qu'est-ce que la prévention cardio-vasculaire secondaire et quelles sont ses exigences ?","a":"<p>La prévention cardio-vasculaire secondaire s'applique à un sujet ayant <strong>déjà présenté un accident vasculaire</strong> ou porteur de <strong>lésions vasculaires documentées</strong>. Son objectif est de <strong>réduire le risque de récidive</strong> et de ralentir la progression des lésions.</p><p>Elle répond à quatre exigences (mnémotechnique : <strong>Systématique, Multirisque, Intensive, Médicalisée</strong>) :<ul><li><strong>Systématique</strong> : pour tout sujet ayant présenté un accident vasculaire ou ayant une atteinte athéroscléreuse.</li><li><strong>Multirisque</strong> : tous les facteurs de risque sont pris en compte.</li><li><strong>Intensive</strong> : prise en charge optimale pour chaque facteur.</li><li><strong>Médicalisée</strong> : le recours aux médicaments est la règle, avec un suivi médical régulier.</li></ul>"},{"i":"44e74355c317","n":222,"o":"222-10","u":"Prise en charge","t":"Connaître le bénéfice de l’activité physique pour la prise en charge du risque cardiovasculaire","q":"Quel est le rôle de l'activité physique régulière dans la prévention cardiovasculaire ?","a":"<p>L'activité physique régulière est un <strong>facteur protecteur cardiovasculaire</strong>. Elle est recommandée en <strong>prévention primaire</strong>, chez les sujets sans antécédents cardiovasculaires, et en <strong>prévention secondaire</strong>, chez les sujets ayant déjà présenté un événement cardiovasculaire.</p>"},{"i":"5644766d9f6b","n":222,"o":"222-10","u":"Prise en charge","t":"Connaître le bénéfice de l’activité physique pour la prise en charge du risque cardiovasculaire","q":"Sur quels facteurs de risque cardiovasculaire l'activité physique agit-elle favorablement ?","a":"<p>L'activité physique agit favorablement sur plusieurs facteurs de risque cardiovasculaire :</p><ul><li>Les <strong>excès de poids</strong>.</li><li>L'<strong>hypertension artérielle (HTA)</strong>.</li><li>L'<strong>équilibre glycémique</strong>.</li><li>L'<strong>équilibre lipidique</strong>.</li></ul>"},{"i":"63aa015e8b85","n":222,"o":"222-10","u":"Prise en charge","t":"Connaître le bénéfice de l’activité physique pour la prise en charge du risque cardiovasculaire","q":"Comment l'activité physique s'intègre-t-elle dans la stratégie globale de prévention cardiovasculaire ?","a":"<p>L'activité physique s'intègre pleinement aux <strong>mesures hygiéno-diététiques</strong>, formant le <strong>socle de toute stratégie de prévention</strong> cardiovasculaire. Elle permet notamment la <strong>lutte contre la sédentarité</strong> dans le contrôle des FRCV en prévention secondaire (volet « C » du moyen mnémotechnique BASIC).</p>"},{"i":"02bac3303195","n":222,"o":"222-12","u":"Suivi et/ou pronostic","t":"Connaître l’efficacité de la prévention cardiovasculaire centrée sur le patient en soins primaires","q":"Quel est le rôle pivot du médecin généraliste dans la prévention cardiovasculaire centrée sur le patient en soins primaires ?","a":"<p>Le médecin généraliste est l'acteur pivot du <strong>dépistage</strong> et du <strong>contrôle des facteurs de risque cardiovasculaire</strong> (FRCV) en soins primaires.</p>"},{"i":"0ec92244a1ea","n":222,"o":"222-12","u":"Suivi et/ou pronostic","t":"Connaître l’efficacité de la prévention cardiovasculaire centrée sur le patient en soins primaires","q":"Comment doit être menée la prévention cardiovasculaire en prévention secondaire ?","a":"<p>En prévention secondaire, la prévention cardiovasculaire doit être :</p><ul><li><strong>Systématique</strong></li><li><strong>Intensive</strong></li><li><strong>Médicalisée</strong></li><li>Accompagnée d'un <strong>suivi régulier</strong></li></ul>"},{"i":"2a42997269c5","n":222,"o":"222-12","u":"Suivi et/ou pronostic","t":"Connaître l’efficacité de la prévention cardiovasculaire centrée sur le patient en soins primaires","q":"Quelle évaluation doit être réalisée pour un patient avec au moins un facteur de risque cardiovasculaire en prévention primaire ?","a":"<p>Une <strong>évaluation globale du risque cardiovasculaire</strong> doit être réalisée pour tout patient présentant <strong>au moins un facteur de risque cardiovasculaire</strong> en prévention primaire.</p>"},{"i":"2e270e3dc7f1","n":222,"o":"222-12","u":"Suivi et/ou pronostic","t":"Connaître l’efficacité de la prévention cardiovasculaire centrée sur le patient en soins primaires","q":"Quelles sont les caractéristiques d'une prévention cardiovasculaire efficace en soins primaires ?","a":"<p>Une prévention cardiovasculaire est d'autant plus efficace qu'elle est :</p><ul><li><strong>Multirisque</strong> : tous les facteurs de risque sont pris en compte ensemble.</li><li><strong>Individualisée</strong> : adaptée au profil de risque spécifique du patient.</li></ul>"},{"i":"3d9af04309f4","n":222,"o":"222-2","u":"Définition","t":"Connaître les facteurs de risque majeurs, indépendants, modifiables (tabac, HTA, diabète, dyslipidémie) et non modifiables (âge, sexe masculin, hérédité)","q":"Quels sont les facteurs de risque cardiovasculaires majeurs et indépendants dits non modifiables ?","a":"<ul><li>L'<strong>âge</strong> : > 50 ans chez l'homme et > 60 ans chez la femme.</li><li>Le <strong>sexe masculin</strong> : cette différence s'atténue après la ménopause.</li><li>L'<strong>hérédité</strong> : caractérisée par des antécédents familiaux d'infarctus du myocarde (IDM) ou de mort subite chez un parent du 1er degré masculin survenu avant <strong>55 ans</strong>, ou féminin avant <strong>65 ans</strong>.</li></ul>"},{"i":"44a34754a5b5","n":222,"o":"222-2","u":"Définition","t":"Connaître les facteurs de risque majeurs, indépendants, modifiables (tabac, HTA, diabète, dyslipidémie) et non modifiables (âge, sexe masculin, hérédité)","q":"Quelle est la définition d'un facteur de risque cardiovasculaire et en quoi se distingue-t-il d'un marqueur de risque ?","a":"<p>Un facteur de risque est un élément clinique ou biologique associé à une augmentation du risque de développer une maladie, avec une <strong>relation de causalité</strong>. Sa suppression entraîne une baisse de l'incidence de la maladie ou de ses complications.</p><p>Il se distingue d'un marqueur de risque qui est un simple témoin de la maladie, <strong>sans lien causal établi</strong>. La diminution d'un marqueur de risque ne modifie pas le pronostic de la maladie (ex: la plaque carotidienne à l'échographie).</p>"},{"i":"4e2caa63f63b","n":222,"o":"222-2","u":"Définition","t":"Connaître les facteurs de risque majeurs, indépendants, modifiables (tabac, HTA, diabète, dyslipidémie) et non modifiables (âge, sexe masculin, hérédité)","q":"Quels sont les facteurs de risque cardiovasculaires majeurs et indépendants dits modifiables ?","a":"<ul><li>Le <strong>tabagisme</strong> : en cours ou sevré depuis <strong>moins de 3 ans</strong>.</li><li>L'<strong>hypertension artérielle</strong> (HTA).</li><li>Le <strong>diabète</strong> (traité ou non), le risque apparaissant généralement après 15 à 20 ans d'évolution.</li><li>La <strong>dyslipidémie</strong> : notamment l'hypercholestérolémie avec une augmentation du <strong>LDLc</strong> et une diminution du <strong>HDLc</strong>.</li></ul>"},{"i":"b252ca00e906","n":222,"o":"222-3","u":"Définition","t":"Connaître l’agrégation de facteurs de risque et facteurs de risque indirects (obésité, sédentarité, syndrome métabolique)","q":"Selon la classification IDF (2005), quels sont les critères diagnostiques du syndrome métabolique ?","a":"<p>Le <strong>tour de taille est un critère obligatoire</strong>, auquel s'ajoutent <strong>au moins 2 critères sur les 4 restants</strong> :</p><ul><li><strong>Tour de taille</strong> (critère obligatoire) :</li><ul><li>Européens : ≥ 94 cm chez l'homme, ≥ 80 cm chez la femme.</li><li>Asiatiques : ≥ 90 cm chez l'homme, ≥ 80 cm chez la femme.</li></ul><li><strong>Pression artérielle</strong> : ≥ 130/85 mmHg.</li><li><strong>Glycémie à jeun</strong> : ≥ 1 g/L.</li><li><strong>Triglycérides</strong> : ≥ 1,50 g/L.</li><li><strong>HDL-cholestérol</strong> : &lt; 0,40 g/L chez l'homme, &lt; 0,50 g/L chez la femme.</li></ul>"},{"i":"bd96c9dc5ea1","n":222,"o":"222-3","u":"Définition","t":"Connaître l’agrégation de facteurs de risque et facteurs de risque indirects (obésité, sédentarité, syndrome métabolique)","q":"Quels sont les principaux facteurs de risque cardiovasculaire indirects mentionnés ?","a":"<ul><li>Le <strong>surpoids et l'obésité</strong> (particulièrement l'obésité abdominale).</li><li>Le <strong>syndrome métabolique</strong>.</li><li>La <strong>sédentarité</strong> (manque d'activité physique régulière).</li><li>L'<strong>insuffisance rénale chronique</strong> (qui classe d'emblée le patient à haut risque).</li><li>Les <strong>facteurs psychosociaux</strong> (conditions socio-économiques défavorables).</li></ul>"},{"i":"dbedfc6ce9b3","n":222,"o":"222-3","u":"Définition","t":"Connaître l’agrégation de facteurs de risque et facteurs de risque indirects (obésité, sédentarité, syndrome métabolique)","q":"Selon la classification NCEP-ATP III (2005), quels sont les critères diagnostiques du syndrome métabolique ?","a":"<p>Il faut au moins <strong>3 critères sur 5</strong> parmi les suivants :</p><ul><li><strong>Tour de taille</strong> : ≥ 102 cm chez l'homme, ≥ 88 cm chez la femme.</li><li><strong>Pression artérielle</strong> : ≥ 130/85 mmHg.</li><li><strong>Glycémie à jeun</strong> : ≥ 1 g/L.</li><li><strong>Triglycérides</strong> : ≥ 1,50 g/L.</li><li><strong>HDL-cholestérol</strong> : &lt; 0,40 g/L chez l'homme, &lt; 0,50 g/L chez la femme.</li></ul>"},{"i":"e832ce4dc805","n":222,"o":"222-3","u":"Définition","t":"Connaître l’agrégation de facteurs de risque et facteurs de risque indirects (obésité, sédentarité, syndrome métabolique)","q":"Qu'est-ce que l'agrégation de facteurs de risque cardiovasculaire ?","a":"<p>L'agrégation de facteurs de risque cardiovasculaire est la <strong>coexistence chez un même patient de plusieurs facteurs de risque</strong>. Elle justifie une <strong>évaluation globale</strong> du risque plutôt qu'une analyse isolée de chaque facteur.</p>"},{"i":"2c8573c2f1b3","n":222,"o":"222-4","u":"Définition","t":"Connaître les stratégies individuelles de prévention : mesures hygiéno-diététiques et traitements médicamenteux","q":"Quelle est l'ordonnance type en prévention secondaire après un infarctus du myocarde (IDM) ?","a":"<p>L'ordonnance type en prévention secondaire après un IDM est résumée par le moyen mnémotechnique BASIC :</p><ul><li><strong>B</strong> : <strong>Beta-bloquant</strong> (uniquement en post-IDM).</li><li><strong>A</strong> : <strong>Antiagrégant plaquettaire</strong> (systématique).</li><li><strong>S</strong> : <strong>Statine</strong> (avec une cible de LDLc <strong>< 0,55 g/L</strong>).</li><li><strong>I</strong> : <strong>IEC</strong> (Inhibiteur de l'Enzyme de Conversion).</li><li><strong>C</strong> : <strong>Contrôle des Facteurs de Risque Cardiovasculaire</strong> (arrêt du tabac, contrôle de la PA et de la glycémie, lutte contre la sédentarité).</li></ul>"},{"i":"8e595e69565e","n":222,"o":"222-4","u":"Définition","t":"Connaître les stratégies individuelles de prévention : mesures hygiéno-diététiques et traitements médicamenteux","q":"Comment est graduée l'intensité de la stratégie individuelle de prévention cardiovasculaire ?","a":"<p>L'intensité de la stratégie individuelle de prévention cardiovasculaire, combinant mesures hygiéno-diététiques et traitements médicamenteux, est graduée <strong>selon le niveau de risque cardiovasculaire</strong> du patient.</p>"},{"i":"ae1db180a085","n":222,"o":"222-4","u":"Définition","t":"Connaître les stratégies individuelles de prévention : mesures hygiéno-diététiques et traitements médicamenteux","q":"Quelles sont les principales mesures hygiéno-diététiques recommandées dans la prévention cardiovasculaire ?","a":"<ul><li>Une <strong>alimentation saine</strong>, de type <strong>méditerranéen</strong>, conforme au Programme National Nutrition Santé (PNNS) : riche en fruits, légumes, acides gras insaturés (<strong>huile d'olive</strong>), produits de la mer, et pauvre en viande rouge.</li><li>Une <strong>activité physique régulière</strong>.</li><li>Le <strong>sevrage tabagique</strong>.</li><li>Une <strong>consommation d'alcool modérée</strong>.</li></ul>"},{"i":"b2de368d0410","n":222,"o":"222-4","u":"Définition","t":"Connaître les stratégies individuelles de prévention : mesures hygiéno-diététiques et traitements médicamenteux","q":"Quels traitements médicamenteux sont utilisés en prévention primaire dans la prise en charge des facteurs de risque cardiovasculaire ?","a":"<p>Les traitements médicamenteux en prévention primaire ciblent spécifiquement chaque facteur de risque modifiable et incluent la prise en charge du <strong>tabac</strong>, des <strong>dyslipidémies</strong>, de l'<strong>hypertension artérielle (HTA)</strong> et du <strong>diabète</strong>.</p>"}]};